#!/usr/bin/env node
/**
 * Read-only, built-output SEO contract audit (broad route and internal link coverage).
 * Prerequisite: npm run build
 *
 * Validates static HTML generated by Vite. This is not a replacement for
 * browser tests, HTTP headers, Google-selected canonical or Search Console.
 */
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, resolve, posix } from 'node:path';

const root = resolve('dist');
const origin = 'https://markups.dev';
const errors = [];
const warnings = [];
const report = (severity, file, message) => (severity === 'error' ? errors : warnings).push({ file, message });

if (!existsSync(join(root, 'index.html'))) {
  console.error('Build output missing. Run npm run build before this audit.');
  process.exit(2);
}

function walk(dir) {
  return readdirSync(dir).flatMap((name) => {
    const file = join(dir, name);
    return statSync(file).isDirectory() ? walk(file) : [file];
  });
}
const htmlFiles = walk(root).filter((p) => p.endsWith('.html'));
const htmlByPath = new Map();
for (const file of htmlFiles) {
  const rel = relative(root, file).replaceAll('\\', '/');
  const route = rel === 'index.html' ? '/' : rel.endsWith('/index.html')
    ? '/' + rel.slice(0, -'/index.html'.length)
    : '/' + rel.replace(/\.html$/, '');
  htmlByPath.set(route, file);
}

function attributes(html, attr) {
  const rx = new RegExp('\\b' + attr + '\\s*=\\s*(["\\x27])([^"\\x27]*?)\\1', 'gi');
  return [...html.matchAll(rx)].map((m) => m[2]);
}
const locs = new Set(
  [...readFileSync(join(root, 'sitemap.xml'), 'utf8').matchAll(/<loc>\s*([^<]+)\s*<\/loc>/g)]
    .map((m) => m[1].trim())
);
const seenCanonicals = new Map();
for (const [route, file] of htmlByPath) {
  const rel = relative(root, file).replaceAll('\\', '/');
  const html = readFileSync(file, 'utf8');
  const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.trim();
  const h1 = /<h1(?:\s|>)/i.test(html);
  const robots = html.match(/<meta\b[^>]*name=["']robots["'][^>]*content=["']([^"']+)["']/i)?.[1] ?? '';
  const noindex = /\bnoindex\b/i.test(robots);
  const canonical = html.match(/<link\b[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i)?.[1];
  const url = origin + route;
  if (!title) report('error', rel, 'missing nonempty title');
  if (!h1) report('warning', rel, 'missing H1 in statically rendered HTML');
  // Error pages and other deliberately noindex pages do not need a canonical.
  // Do not force a bogus canonical for /404 just to pass an SEO check.
  if (!canonical && !noindex) report('error', rel, 'missing canonical on indexable page');
  if (route === '/404' && !noindex) report('error', rel, '404 page must be noindex');
  if (canonical && !canonical.startsWith(origin + '/')) report('error', rel, 'off-domain canonical: ' + canonical);
  if (canonical && seenCanonicals.has(canonical) && canonical !== origin + '/') {
    report('warning', rel, 'shared canonical with ' + seenCanonicals.get(canonical));
  }
  if (canonical) seenCanonicals.set(canonical, rel);
  if (noindex && locs.has(url)) report('error', rel, 'noindex URL appears in sitemap: ' + url);
  if (!noindex && canonical === url && route.startsWith('/seo/') && !locs.has(url)) {
    report('error', rel, 'self-canonical indexable SEO route missing from sitemap');
  }

  for (const value of attributes(html, 'href')) {
    if (!value || value[0] === '#' || /^(?:mailto:|tel:|javascript:|data:|blob:)/i.test(value)) continue;
    let parsed;
    try { parsed = new URL(value, url); } catch { continue; }
    if (parsed.origin !== origin) continue;
    const pathname = decodeURIComponent(parsed.pathname).replace(/\/+$/, '') || '/';
    const target = htmlByPath.has(pathname) || existsSync(join(root, pathname.slice(1)));
    if (!target) report('error', rel, 'broken same-domain link: ' + value);
  }
  for (const value of attributes(html, 'src')) {
    if (!value || /^(?:data:|blob:)/i.test(value)) continue;
    let parsed;
    try { parsed = new URL(value, url); } catch { continue; }
    // Vercel injects this platform script at runtime, outside dist.
    if (parsed.origin !== origin || parsed.pathname.startsWith('/_vercel/')) continue;
    if (!existsSync(join(root, decodeURIComponent(parsed.pathname).slice(1)))) {
      report('error', rel, 'broken same-domain resource: ' + value);
    }
  }
  const og = html.match(/<meta\s+property=["']og:image["']\s+content=["']([^"']+)["']/i)?.[1];
  if (og) {
    try {
      const parsed = new URL(og);
      if (parsed.origin === origin && !existsSync(join(root, parsed.pathname.slice(1)))) {
        report('error', rel, 'broken og:image asset ' + og);
      }
    } catch { report('error', rel, 'invalid og:image URL ' + og); }
  }
  for (const data of [...html.matchAll(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)]) {
    try { JSON.parse(data[1]); }
    catch (e) { report('error', rel, 'JSON-LD parse error: ' + e.message); }
  }
}
for (const loc of locs) {
  if (!loc.startsWith(origin + '/')) {
    report('error', 'sitemap.xml', 'off-domain sitemap loc ' + loc);
    continue;
  }
  const route = new URL(loc).pathname.replace(/\/+$/, '') || '/';
  const file = htmlByPath.get(route);
  if (file) {
    const html = readFileSync(file, 'utf8');
    const canonical = html.match(/<link\b[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i)?.[1];
    if (canonical !== loc) report('error', 'sitemap.xml', 'sitemap URL differs from page canonical: ' + loc);
  }
  if (!file && !existsSync(join(root, route.slice(1)))) {
    report('error', 'sitemap.xml', 'listed route absent from dist: ' + route);
  }
}
const result = {
  command: 'node scripts/qa/audit-built-site.mjs',
  build: root, htmlPages: htmlFiles.length, sitemapURLs: locs.size,
  errorCount: errors.length, warningCount: warnings.length, errors, warnings,
  limitations: 'static build output only; HTTP routing, JS rendering, accessibility, Google indexing and AI search recommendations not measured'
};
console.log(JSON.stringify(result, null, 2));
if (errors.length) process.exitCode = 1;
